def restore_tree(n, edges):
    from collections import defaultdict, deque

    # Create adjacency list for the tree
    tree = defaultdict(list)
    for i, (p_i, _) in enumerate(edges, start=1):
        tree[p_i].append(i)

    # Initialize the result array
    a = [0] * n

    # Find the root of the tree
    root = None
    for i in range(n):
        if edges[i][0] == 0:
            root = i + 1
            break

    # Perform a topological sort to determine the order of vertices
    in_degree = [0] * (n + 1)
    for p_i, _ in edges:
        if p_i != 0:
            in_degree[p_i] += 1

    queue = deque([root])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for child in tree[node]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                queue.append(child)

    # Try to assign values to a_i based on the given c_i
    for node in order:
        p_i, c_i = edges[node - 1]
        if c_i == 0:
            a[node - 1] = 1  # Assign the minimum possible value
        else:
            candidates = []
            for parent in tree:
                if parent != p_i and all(a[child - 1] < a[node - 1] for child in tree[parent]):
                    candidates.append(a[parent - 1])
            if not candidates:
                return "NO"
            a[node - 1] = max(candidates) + 1

    return "YES\n" + " ".join(map(str, a))

